    def maxArrayValue(self, nums: List[int]) -> int:
        from typing import List
        if not nums:
            return 0
        uniq = sorted(set(nums))
        rank = {v: i + 1 for i, v in enumerate(uniq)}
        size = len(uniq) + 2
        bit = [0] * size

        def update(i: int, val: int):
            while i < size:
