    def maximumSum(self, nums: List[int]) -> int:
        import math
        from collections import defaultdict

        if not nums:
            return 0

        max_num = max(nums)
        limit = int(math.isqrt(max_num)) + 1

        # Sieve of Eratosthenes to generate primes up to limit
        is_prime = [True] * (limit + 1)
        primes = []
        for i in range(2, limit + 1):
            if is_prime[i]:
                primes.append(i)
                for j in range(i * i, limit + 1, i):
                    is_prime[j] = False

        def squarefree_part(x: int) -> int:
            if x == 0:
                return 0
            x = abs(x)
            s = 1
            tmp = x
            for p in primes:
                if p * p > tmp:
                    break
                if tmp % p == 0:
                    parity = 0
                    while tmp % p == 0:
                        tmp //= p
                        parity ^= 1
                    if parity == 1:
                        s *= p
            if tmp > 1:
                s *= tmp
            return s

        groups = defaultdict(int)
        for val in nums:
            sf = squarefree_part(val)
            groups[sf] += val

        return max(groups.values()) if groups else 0

class Solution:
    def maxIncreasingGroups(self, usageLimits: List[int]) -> int:
        nums = []
        for v in usageLimits:
            try:
                iv = int(v)
            except Exception:
                continue
            if iv < 0:
                continue
            nums.append(iv)
        nums.sort()
        next_size = 1
